const out=['photo '+photo.type+' '+Math.round(photo.width)+'x'+Math.round(photo.height)+' layoutMode='+photo.layoutMode+' sizing='+photo.primaryAxisSizingMode+'/'+photo.counterAxisSizingMode];
out.push('main: '+photo.mainComponent.name+' '+Math.round(photo.mainComponent.width)+'x'+Math.round(photo.mainComponent.height)+' layoutMode='+photo.mainComponent.layoutMode);
out.push('children: '+photo.children.map(c=>c.type+' '+c.name+' '+Math.round(c.width)+'x'+Math.round(c.height)+' sizing='+(c.layoutSizingHorizontal||'-')+'/'+(c.layoutSizingVertical||'-')).join(' | '));
return out.join('\n');

